// Real Geographic Navigation Data for Northeast Corridor (Guwahati -> Imphal)
// Based on real National Highway network (NH-27, NH-29, NH-2)

export interface GeoCoordinate {
  lat: number;
  lng: number;
}

export interface RouteWaypoint {
  id: string;
  name: string;
  state: string;
  highway: string;
  lat: number;
  lng: number;
  type: 'origin' | 'destination' | 'major_junction' | 'checkpoint';
  description?: string;
}

export interface RealTollGate {
  id: string;
  name: string;
  highway: string;
  cost: number;
  location: string;
  lat: number;
  lng: number;
  laneCount: number;
  fastag: boolean;
}

export interface RealTrafficSignal {
  id: string;
  name: string;
  highway: string;
  location: string;
  lat: number;
  lng: number;
  status: 'green' | 'yellow' | 'red';
  durationSec: number;
}

export interface RealRiskAlert {
  id: string;
  category: 'Landslide' | 'Flood' | 'Road Blockage' | 'Poor Road Condition' | 'Low Visibility' | 'Bridge Restriction';
  title: string;
  location: string;
  state: string;
  highway: string;
  severity: 'LOW' | 'MEDIUM' | 'HIGH';
  status: string;
  advisory: string;
  lat: number;
  lng: number;
  icon: string;
}

export interface RealServicePoint {
  id: string;
  name: string;
  type: 'fuel' | 'hospital' | 'repair' | 'parking' | 'warehouse';
  categoryLabel: string;
  location: string;
  distanceKm: number;
  travelTime: string;
  status: string;
  phone: string;
  lat: number;
  lng: number;
  highway: string;
}

